const titles={recipes:'Food',notes:'Notes',cars:'Cars',todos:'To-Dos',settings:'Settings'};
const RECIPE_CATEGORIES=['Meals','Baked Goods','Desserts','Sides','Sauces'];
const recipeCategory=recipe=>RECIPE_CATEGORIES.includes(recipe?.category)?recipe.category:'Meals';
const noteCategory=note=>String(note?.category||'General').trim()||'General';
const noteUpdatedAt=note=>String(note?.updatedAt||note?.createdAt||note?.date||'');
const noteUpdatedLabel=note=>{const stamp=noteUpdatedAt(note),date=/^\d{4}-\d{2}-\d{2}/.exec(stamp)?.[0];return date?`Last updated ${dateLabel(date)}`:'Last updated date unavailable'};
const NOTE_HUBS={
 homeManual:{id:'note_hub_home_manual',title:"Home Owner's Manual",category:'Home',description:'Rooms, appliances, systems, contacts, warranties, and maintenance.'},
 packing:{id:'note_hub_packing',title:'Packing Lists',category:'Travel',description:'A master packing template and independent trip checklists.'},
 photography:{id:'note_hub_photography',title:'Photography Reference',category:'Photography',description:'Camera setups, quick settings, field notes, and example photos.'}
};
const NOTE_HUB_KINDS=new Set(Object.keys(NOTE_HUBS));
const noteKind=note=>NOTE_HUB_KINDS.has(note?.noteKind)?note.noteKind:'standard';
const noteHubDefinition=note=>NOTE_HUBS[noteKind(note)]||null;
const isNoteHub=note=>note?.type==='note'&&noteKind(note)!=='standard';
const noteTypeLabel=note=>noteKind(note)==='standard'?'Note':({homeManual:"Home Owner's Manual",packing:'Packing Lists',photography:'Photography Reference'})[noteKind(note)];
const hubViewState=new Map();
function flattenHubText(value,output=[]){if(typeof value==='string')output.push(plainRichText(value,/<[a-z][\s\S]*>/i.test(value)));else if(Array.isArray(value))value.forEach(item=>flattenHubText(item,output));else if(value&&typeof value==='object')for(const [key,item]of Object.entries(value))if(!['photos','publicId','url'].includes(key))flattenHubText(item,output);return output}
function noteSearchText(note){return isNoteHub(note)?[note.title,note.category,noteTypeLabel(note),...flattenHubText(note)].join('\n'):[note.title,plainRichText(note.body,note.richText)].join('\n')}
function missingNoteHubs(){return Object.entries(NOTE_HUBS).filter(([kind,definition])=>!records.some(record=>record.id===definition.id&&record.type==='note'&&!record.deleted&&noteKind(record)===kind))}
function noteCategories(){const categories=new Map();for(const note of listType('note')){const category=noteCategory(note),key=category.toLocaleLowerCase();if(!categories.has(key))categories.set(key,category)}return [...categories.values()].sort((a,b)=>a.localeCompare(b,undefined,{sensitivity:'base'}))}
const categoryFilter=(type,value)=>`${type}:${encodeURIComponent(value)}`;
const filteredCategory=value=>{try{return decodeURIComponent(value.slice(value.indexOf(':')+1))}catch{return ''}};
const UPLOAD_SIGNER='https://red-ridge-upload-signer.allenkevinc.workers.dev/sign';
let tab='recipes',foodView='recipes',filter='all',query='',selected=null,user=null,records=[],photos=new Map(),cloud=null,cloudPromise=null,loaded=false,photoLoaded=false,toastTimer,pending=0,failedOps=[],lastSyncError='',installPrompt=null,listMarkup='',searchTimer=0,photoWatch=false;
let renderFrame=0,renderFlags={list:false,detail:false,status:false};
const HISTORY_KEY='red-ridge-view',HISTORY_TABS=new Set(Object.keys(titles)),HISTORY_FOOD_VIEWS=new Set(['recipes','ingredients']);
let currentViewState=null,restoringView=false;
function viewState(){return {[HISTORY_KEY]:true,tab,foodView,filter,query,selected}}
function sameView(a,b){return !!a&&!!b&&a[HISTORY_KEY]&&b[HISTORY_KEY]&&a.tab===b.tab&&a.foodView===b.foodView&&a.filter===b.filter&&a.query===b.query&&a.selected===b.selected}
function restoreView(state){if(!state?.[HISTORY_KEY])return false;tab=HISTORY_TABS.has(state.tab)?state.tab:'recipes';foodView=HISTORY_FOOD_VIEWS.has(state.foodView)?state.foodView:'recipes';filter=typeof state.filter==='string'?state.filter:'all';query=typeof state.query==='string'?state.query:'';selected=typeof state.selected==='string'?state.selected:null;return true}
function writeViewHistory(replace=false){if(restoringView)return;const next=viewState();if(sameView(currentViewState,next))return;history[replace?'replaceState':'pushState'](next,'');currentViewState=next}
function dismissTopDialog(){const dialog=$$('dialog[open]').at(-1);if(!dialog)return false;const close=dialog.querySelector('#no,[data-close],#closeCloudinary,#closePhoto');if(close)close.click();else dialog.close();return true}
function appBack(){history.back()}
function initializeViewHistory(){const initial=history.state?.[HISTORY_KEY]?history.state:viewState();restoreView(initial);currentViewState=viewState();history.replaceState(currentViewState,'');history.pushState(currentViewState,'')}
window.addEventListener('popstate',event=>{const leaving=currentViewState;if(dismissTopDialog()){history.pushState(leaving||viewState(),'');currentViewState=leaving||viewState();return}if(!event.state?.[HISTORY_KEY])return;if(sameView(leaving,event.state)){history.back();return}const from=leaving?.selected,fromTab=leaving?.tab,fromFood=leaving?.foodView;restoreView(event.state);currentViewState=viewState();const update=()=>{restoringView=true;render();restoringView=false},direction=fromTab&&(fromTab!==tab||fromFood!==foodView)?tabDirection(fromTab,tab,fromFood,foodView):from&&!selected?'back':!from&&selected?'forward':'';if(direction)withViewTransition(direction,update);else update()});
let trusted=(localStorage.getItem('red-ridge-trusted')??localStorage.getItem('daily-trusted'))==='true';
const dateLabel=s=>{if(!s)return '';const d=new Date(s+'T12:00:00');return isNaN(d)?s:d.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})};
// Lookup tables are rebuilt lazily when records change (replaced or passed through applyOps) or the day rolls over.
let recordIndex=null;const markRecordsChanged=()=>{recordIndex=null};
function recordTables(){const date=localDate();if(recordIndex?.source===records&&recordIndex.date===date)return recordIndex;const byId=new Map(),byType=new Map();for(const r of records){if(!byId.has(r.id))byId.set(r.id,r);if(r.deleted)continue;if(!byType.has(r.type))byType.set(r.type,[]);byType.get(r.type).push(r)}const recurring=recurringTodos(records,date);return recordIndex={source:records,date,byId,byType,recurring,recurringById:new Map(recurring.map(r=>[r.id,r]))}}
const get=id=>{const tables=recordTables();return tables.byId.get(id)||tables.recurringById.get(id)};const listType=t=>{const tables=recordTables(),saved=tables.byType.get(t)||[];return t==='todo'?saved.concat(tables.recurring):saved.slice()};
const alpha=(a,b)=>String(a.title||'').localeCompare(String(b.title||''),undefined,{sensitivity:'base'});
const ingredients=()=>listType('ingredient').sort(alpha),ingredientTags=()=>listType('ingredientTag').sort(alpha);
const ingredientName=id=>get(id)?.title||'Missing ingredient';
const ingredientTagNames=item=>(item.tagIds||[]).map(id=>get(id)?.title).filter(Boolean).sort((a,b)=>a.localeCompare(b,undefined,{sensitivity:'base'}));
const recipesUsing=id=>listType('recipe').filter(recipe=>recipe.recipeIngredients?.some(item=>item.ingredientId===id)).sort(alpha);
const readable=r=>r;
const title=r=>r.title;
const byDate=(a,b)=>String(b.date||b.updatedAt).localeCompare(String(a.date||a.updatedAt));
const carOwnershipDate=car=>car.ownedFrom||car.ownedTo||car.createdAt||car.updatedAt||'';
const dayNumber=s=>{const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(String(s||''));return m?Date.UTC(Number(m[1]),Number(m[2])-1,Number(m[3]))/86400000:NaN};
const mixColor=(from,to,amount)=>{const a=from.match(/[\da-f]{2}/gi).map(v=>parseInt(v,16)),b=to.match(/[\da-f]{2}/gi).map(v=>parseInt(v,16));return '#'+a.map((v,i)=>Math.round(v+(b[i]-v)*amount).toString(16).padStart(2,'0')).join('')};
const TODO_GRADIENTS={warm:['#E32960','#F9732F','#FEA000'],cool:['#007DC2','#00AB6C','#8AD928']};
function todoPalette(date){const days=dayNumber(date)-dayNumber(localDate());if(Number.isFinite(days)&&days<=0)return 'urgent';return !Number.isFinite(days)||days<=60?'warm':'cool'}
function gradientPosition(index,total){if(total<=1)return 50;if(total<=11)return 50+(index-(total-1)/2)*10;if(total<=101)return index*100/(total-1);return index%101}
function gradientColor(colors,percent){return percent<=50?mixColor(colors[0],colors[1],percent/50):mixColor(colors[1],colors[2],(percent-50)/50)}
function paletteRowColors(palette,index,total){const base=gradientColor(palette,gradientPosition(index,total));return {top:mixColor(base,'#ffffff',.0225),bottom:mixColor(base,'#000000',.0225)}}
function recipeCardColor(index,total){return paletteRowColors(TODO_GRADIENTS.warm,index,total)}
function noteCardColor(index,total){return paletteRowColors(TODO_GRADIENTS.cool,index,total)}
function todoColorSlots(items){const groups={warm:[],cool:[]},slots=new Map();for(const item of items){const palette=todoPalette(item.date);if(palette!=='urgent')groups[palette].push(item)}for(const palette of ['warm','cool'])groups[palette].forEach((item,index)=>slots.set(item.id,{index,total:groups[palette].length}));return slots}
// To-Do rows sit under a 20% black overlay so the palette reads calmer than the recipe bands.
function todoRowColors(date,index=0,total=1){const palette=todoPalette(date);return palette==='urgent'?paletteRowColors(['#E71C44','#E71C44','#E71C44'],0,1):paletteRowColors(TODO_GRADIENTS[palette],index,total)}
function shortTodoDate(date){const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(String(date||''));return m?`${m[2]}/${m[3]}/${m[1].slice(2)}`:''}
function parseTodoDate(value){const m=/^(\d{1,2})\/(\d{1,2})\/(\d{2})$/.exec(String(value||'').trim());if(!m)throw Error('Enter the due date as MM/DD/YY.');const month=Number(m[1]),day=Number(m[2]),year=2000+Number(m[3]),d=new Date(year,month-1,day,12);if(d.getFullYear()!==year||d.getMonth()!==month-1||d.getDate()!==day)throw Error('Enter a valid due date in the 21st century.');return `${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`}
