 const active=ordered(false),done=ordered(true);
 const slots=todoColorSlots(active);
 const row=t=>{const link=firstTodoLink(t.title),slot=slots.get(t.id),colors=todoRowColors(t.date,slot?.index,slot?.total);return `<li class="task-wrap ${t.done?'done':''}" data-id="${e(t.id)}"><div class="underlay complete"><span>✓ ${t.done?'Restore':'Complete'}</span></div><div class="underlay delete"><span>Delete ×</span></div><div class="task-row" tabindex="0" role="button" aria-label="Edit ${e(t.title)}" style="--band-top:${colors.top};--band-bottom:${colors.bottom}"><div class="task-label">${t.date?`<small>${e(dateLabel(t.date))}${!t.done&&t.date<localDate()?' · Overdue':''}</small>`:''}<span data-text="${e(link.text)}">${linkify(link.text)}</span></div>${link.url?`<a class="todo-web-link" href="${e(link.url)}" target="_blank" rel="noopener noreferrer" aria-label="Open link for ${e(t.title)}">${icon('web')}</a>`:''}</div></li>`};
