 const reset=()=>{row.classList.remove('dragging');wrap.classList.remove('swiping-right','swiping-left');row.style.transform=''};
 row.onpointerdown=ev=>{if(ev.target.closest('a')||ev.button!==0)return;pointer=ev.pointerId;sx=ev.clientX;sy=ev.clientY;dx=0;horizontal=moved=vertical=false;row.setPointerCapture?.(pointer)};
 row.onpointermove=ev=>{if(ev.pointerId!==pointer||vertical)return;const x=ev.clientX-sx,y=ev.clientY-sy;if(!horizontal&&Math.abs(y)>8&&Math.abs(y)>Math.abs(x)){vertical=true;moved=true;return}if(!horizontal&&Math.abs(x)>8&&Math.abs(x)>Math.abs(y))horizontal=true;if(!horizontal)return;ev.preventDefault();moved=true;dx=done?Math.max(0,Math.min(240,x)):Math.max(-240,Math.min(240,x));row.classList.add('dragging');row.style.transform=`translateX(${dx}px)`;wrap.classList.toggle('swiping-right',dx>12);wrap.classList.toggle('swiping-left',!done&&dx< -12)};
 row.onpointerup=ev=>{if(ev.pointerId!==pointer)return;pointer=null;const r=get(wrap.dataset.id);if(done&&dx>=threshold()){row.classList.remove('dragging');row.classList.add('completing');navigator.vibrate?.(12);setTimeout(()=>setTodoDone(r,false),180);return}if(!done&&Math.abs(dx)>=threshold()){navigator.vibrate?.(12);if(dx>0){row.classList.remove('dragging');row.classList.add('completing');setTimeout(()=>setTodoDone(r,true),180)}else{reset();removeTodo(r)}return}reset();if(!moved)openEditor(r)};
 row.onpointercancel=()=>{pointer=null;reset()};
