function newNoteHub(kind){const definition=NOTE_HUBS[kind],stamp=new Date().toISOString(),base={id:definition.id,type:'note',noteKind:kind,title:definition.title,category:definition.category,pinned:false,createdAt:stamp,updatedAt:stamp};if(kind==='homeManual')return {...base,homeItems:[],homeHistory:[],homeContacts:[]};if(kind==='packing')return {...base,packingTemplate:[],packingTrips:[]};return {...base,photoGuides:[]}}
function openNoteCreator(){const missing=missingNoteHubs();if(!missing.length){openEditor(null,'note');return}const d=$('#editor');d.innerHTML=`<div class="modal-head"><h2>New note</h2><button class="text-button" type="button" data-close aria-label="Close">×</button></div><div class="form-body"><p class="small">Standard notes are unlimited. Each rich reference can be created once.</p><div class="note-type-grid"><button class="note-type-choice" data-note-type="standard"><strong>Standard note</strong><span>A flexible title and rich-text note.</span></button>${missing.map(([kind,definition])=>`<button class="note-type-choice" data-note-type="${e(kind)}"><strong>${e(definition.title)}</strong><span>${e(definition.description)}</span></button>`).join('')}</div></div>`;d.querySelectorAll('[data-close]').forEach(button=>button.onclick=()=>d.close());d.querySelectorAll('[data-note-type]').forEach(button=>button.onclick=async()=>{const kind=button.dataset.noteType;d.close();if(kind==='standard'){openEditor(null,'note');return}const hub=newNoteHub(kind);await save(hub,{waitForServer:navigator.onLine});tab='notes';filter='all';selected=hub.id;hubViewState.delete(hub.id);writeViewHistory();render();toast(`${hub.title} created`)});d.oncancel=event=>{event.preventDefault();d.close()};d.showModal()}
