const pairLines=items=>(items||[]).map(item=>`${item.label||''} | ${item.value||''}`).join('\n');
function parsePairLines(value,max=100){return String(value||'').split(/\r?\n/).map(line=>line.trim()).filter(Boolean).slice(0,max).map(line=>{const index=line.indexOf('|');return {id:crypto.randomUUID(),label:(index<0?line:line.slice(0,index)).trim(),value:(index<0?'':line.slice(index+1)).trim()}}).filter(item=>item.label||item.value)}
