function bindRecipeIngredientEditor(form,drafts,markDirty){const container=form.querySelector('#recipeIngredientRows');if(!container)return;const refreshOptions=()=>{form.querySelector('#ingredient-options')?.remove();container.insertAdjacentHTML('afterend',ingredientDatalist(drafts))};const bindRow=row=>{const input=row.querySelector('[name=ingredientName]'),add=row.querySelector('.inline-ingredient-add');const resolve=()=>{const match=ingredientLookup(input.value,drafts);input.dataset.ingredientId=match?.id||'';const name=input.value.trim();add.hidden=!name||!!match;add.textContent=name?`Add “${name}” to Ingredients`:''};input.addEventListener('input',()=>{resolve();markDirty()});input.addEventListener('change',resolve);add.onclick=()=>{const name=input.value.trim();if(!name)return;const found=ingredientLookup(name,drafts);if(found){input.dataset.ingredientId=found.id;input.value=found.title}else{const item={id:crypto.randomUUID(),type:'ingredient',title:name,aliases:[],tagIds:[],hidden:false,body:'',substitutes:'',photos:[],richText:true,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};drafts.set(item.id,item);input.dataset.ingredientId=item.id;input.value=item.title;refreshOptions()}add.hidden=true;markDirty()};row.querySelector('.ingredient-remove').onclick=()=>{if(container.children.length===1){row.querySelectorAll('input').forEach(field=>field.value='');input.dataset.ingredientId='';resolve()}else row.remove();markDirty()};resolve()};container.querySelectorAll('.recipe-ingredient-row').forEach(bindRow);$('#addIngredientRow').onclick=()=>{container.insertAdjacentHTML('beforeend',recipeIngredientRow());bindRow(container.lastElementChild);markDirty()};let dragged=null;container.addEventListener('dragstart',event=>{dragged=event.target.closest('.recipe-ingredient-row');if(!dragged){event.preventDefault();return}dragged.classList.add('dragging')});container.addEventListener('dragover',event=>{if(!dragged)return;event.preventDefault();const target=event.target.closest('.recipe-ingredient-row');if(!target||target===dragged)return;const rect=target.getBoundingClientRect();container.insertBefore(dragged,event.clientY<rect.top+rect.height/2?target:target.nextSibling)});container.addEventListener('dragend',()=>{dragged?.classList.remove('dragging');dragged=null;markDirty()});container.addEventListener('keydown',event=>{const handle=event.target.closest('.ingredient-drag');if(!handle||!event.altKey||!['ArrowUp','ArrowDown'].includes(event.key))return;event.preventDefault();const row=handle.closest('.recipe-ingredient-row'),sibling=event.key==='ArrowUp'?row.previousElementSibling:row.nextElementSibling;if(!sibling)return;if(event.key==='ArrowUp')container.insertBefore(row,sibling);else container.insertBefore(sibling,row);handle.focus();markDirty()});refreshOptions()}
